import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第三十四卦 大壯 雷天大壯 震上乾下","description":"周易 - 第三十四卦 大壯 雷天大壯 震上乾下","frontmatter":{"title":"第三十四卦 大壯 雷天大壯 震上乾下","description":"周易 - 第三十四卦 大壯 雷天大壯 震上乾下"},"headers":[],"relativePath":"classics/zhouyi/035.md","filePath":"classics/zhouyi/035.md"}'),l={name:"classics/zhouyi/035.md"};function t(s,a,n,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="大壯" tabindex="-1">大壯 <a class="header-anchor" href="#大壯" aria-label="Permalink to “大壯”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>利貞。 彖曰：大壯，大者壯也。剛以動，故壯。大壯利貞；大者正也。正大而天地之情可見矣！</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>雷在天上，大壯；君子以非禮勿履。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>壯於趾，徵兇，有孚。象曰：壯於 趾，其孚窮也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>貞吉。象曰：九二貞吉，以中也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>小人用壯，君子用罔，貞厲。羝羊觸藩，羸其角。象曰：小人用壯，君子罔也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>貞吉悔亡，藩決不羸，壯於大輿之輹。象曰：藩決不羸，尚往也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>喪羊於易，無悔。象曰：喪羊於易，位不當也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>羝羊觸藩，不能退，不能遂，無攸利，艱則吉。象曰：不能退，不能遂，不祥也。艱則吉，咎不長也。</p>',17)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
